async function applyTopic(env,id,t){const ts=TS();
 const existing=await env.DB.prepare(`SELECT id FROM content_items WHERE project_id=? AND id=?`).bind(PROJECT,id).first();if(!existing)return{ok:false,id,error:'backlog item missing'};
 const ev=await env.DB.prepare(`SELECT id FROM quote_source_evidence WHERE content_item_id=? AND source_url=? LIMIT 1`).bind(id,t.source).first();if(!ev)await env.DB.prepare(`INSERT INTO quote_source_evidence(content_item_id,source_type,source_title,source_url,source_locator,original_text,original_language,verified,verification_notes,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)`).bind(id,'primary_or_authoritative_text',`${t.author}, ${t.work}`,t.source,t.locator,t.original,t.original_language,1,'Exact source wording and locus verified during WQ pre-production source audit.',ts).run();
 await env.DB.prepare(`UPDATE content_items SET canonical_title=?,source_text=?,source_name=?,source_url=?,quote_type='verbatim',original_quote=?,original_language=?,author_name=?,author_source=?,source_work=?,source_date=?,attribution_status='verified',facts_verified=1,uniqueness_verified=1,source_verified_at=?,source_verification_notes=?,category=?,category_slug=?,status='localized',notes=?,updated_at=? WHERE project_id=? AND id=?`).bind(`${t.author} — ${t.original}`,t.original,t.author,t.source,t.original,t.original_language,t.author,t.source,t.work,t.date,ts,'Verified source; quote-length reviewed; 13 website localizations and 8 active-social localizations prepared under Master Rules v4.9.',t.category,t.category,`Full pre-media package prepared. Awaiting user-generated media after website publication.`,ts,PROJECT,id).run();
 for(const lang of WEB){const q=t.q[lang],vid=`${id}_${lang}_v1`,prompt=SOCIAL.includes(lang)?videoPrompt(lang,t):null;await env.DB.prepare(`INSERT INTO content_versions(id,content_id,language_code,title,adapted_text,voiceover_text,on_screen_text,ai_prompt,status,language_check_status,approved,verification_date,source_urls,editor_notes,version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,1) ON CONFLICT(content_id,language_code,version) DO UPDATE SET title=excluded.title,adapted_text=excluded.adapted_text,voiceover_text=excluded.voiceover_text,on_screen_text=excluded.on_screen_text,ai_prompt=excluded.ai_prompt,status=excluded.status,language_check_status=excluded.language_check_status,approved=excluded.approved,verification_date=excluded.verification_date,source_urls=excluded.source_urls,editor_notes=excluded.editor_notes`).bind(vid,id,lang,`${authorFromQuote(q,t.author)} — ${baseQuote(q)}`,q,q,q,prompt,'native_language_qa','native_qa_pass',1,ts,t.source,'Native-naturalness and semantic-fidelity QA completed; exact source attribution preserved.').run();const slug=slugFor(t,lang),path=`/${lang}/quotes/${slug}/`,body=article(lang,t);await env.DB.prepare(`INSERT INTO quote_pages(id,project_id,content_item_id,content_version_id,language_code,slug,seo_title,meta_description,reflection_title,reflection_body,canonical_path,status,published_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(content_version_id) DO UPDATE SET slug=excluded.slug,seo_title=excluded.seo_title,meta_description=excluded.meta_description,reflection_title=excluded.reflection_title,reflection_body=excluded.reflection_body,canonical_path=excluded.canonical_path,status=CASE WHEN quote_pages.status='published' THEN 'published' ELSE excluded.status END,updated_at=excluded.updated_at`).bind(`QP_${id}_${lang}`,PROJECT,id,vid,lang,slug,`${authorFromQuote(q,t.author)} — ${baseQuote(q).slice(0,100)}`,`${authorFromQuote(q,t.author)}: ${t.insight[lang]}. Verified quote, context and reflection.`,UI[lang]?.meaning||'Meaning and reflection',body,path,'draft',null,ts).run()}
 const pub=await publishWebsite(env,id);if(!pub?.published)return{ok:false,id,error:'website publication gate failed',pub};
 for(const lang of SOCIAL){const url=`https://wisequotesworld.com/${lang}/quotes/${slugFor(t,lang)}/`,s=social(lang,t,url),outs={pinterest_prompt:pinPrompt(lang,t),facebook:s.facebook,instagram:s.instagram,threads:s.threads,tiktok:s.tiktok,youtube_title:s.youtube_title,youtube_description:s.youtube_description,pinterest_title:s.pinterest_title,pinterest_description:s.pinterest_description,website_reflection:article(lang,t),article_url:url};for(const [key,text] of Object.entries(outs))await env.DB.prepare(`INSERT INTO content_outputs(id,project_id,content_item_id,language_code,output_key,output_text,status,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(content_item_id,language_code,output_key) DO UPDATE SET output_text=excluded.output_text,status=excluded.status,updated_at=excluded.updated_at`).bind(`${id}_${lang}_${key}`,PROJECT,id,lang,key,text,'ready',ts).run()}
 await env.DB.prepare(`UPDATE content_versions SET status='media_pending',updated_at=? WHERE content_id=?`).bind(ts,id).run();await env.DB.prepare(`UPDATE content_items SET status='media_pending',notes=?,updated_at=? WHERE project_id=? AND id=?`).bind('Complete pre-media package: verified source; 13 website articles published; 8 active social locales native-QA; video/Pinterest prompts, social copy and article URLs ready. Awaiting media upload.',ts,PROJECT,id).run();return{ok:true,id,published:true,status:'media_pending'} }
export async function prepareBatch018026(env){if(!env?.DB)return{ok:false,error:'DB unavailable'};await ensure(env);const results=[];for(const [id,t] of Object.entries(TOPICS)){const r=await applyTopic(env,id,t);results.push(r);if(!r.ok)return{ok:false,failed:id,results}}return{ok:true,count:results.length,results,readback:await readBatch018026(env)}}
export async function readBatch018026(env){if(!env?.DB)return{ok:false,error:'DB unavailable'};await ensure(env);const rows=[];for(const id of Object.keys(TOPICS)){const item=await env.DB.prepare(`SELECT id,status,quote_type,author_name,source_work,attribution_status,facts_verified FROM content_items WHERE project_id=? AND id=?`).bind(PROJECT,id).first();const pages=await env.DB.prepare(`SELECT COUNT(*) c FROM quote_pages WHERE project_id=? AND content_item_id=? AND status='published'`).bind(PROJECT,id).first();const outs=await env.DB.prepare(`SELECT COUNT(*) c FROM content_outputs WHERE project_id=? AND content_item_id=? AND TRIM(COALESCE(output_text,''))<>''`).bind(PROJECT,id).first();const vers=await env.DB.prepare(`SELECT COUNT(*) c FROM content_versions WHERE content_id=? AND language_check_status='native_qa_pass'`).bind(id).first();const prompts=await env.DB.prepare(`SELECT COUNT(*) c FROM content_versions WHERE content_id=? AND language_code IN ('uk','ru','pl','en','sv','de','es','fr') AND TRIM(COALESCE(ai_prompt,''))<>''`).bind(id).first();rows.push({...item,published_pages:Number(pages?.c||0),outputs:Number(outs?.c||0),native_qa:Number(vers?.c||0),video_prompts:Number(prompts?.c||0),ready_for_user_media:item?.status==='media_pending'&&Number(pages?.c||0)===13&&Number(outs?.c||0)===88&&Number(vers?.c||0)===13&&Number(prompts?.c||0)===8})}return{ok:rows.length===9&&rows.every(x=>x.ready_for_user_media),count:rows.length,rows}}
